import{_ as o,l as i,o as e,c as s,v as l,p as d,x as t,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"模型卡与报告","description":"","frontmatter":{"title":"模型卡与报告","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-cards.md","filePath":"llm/model-cards.md","lastUpdated":1789023840000}'),m={name:"llm/model-cards.md"};function c(E,a,A,_,f,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="模型卡与报告" tabindex="-1">模型卡与报告 <a class="header-anchor" href="#模型卡与报告" aria-label="Permalink to &quot;模型卡与报告&quot;">​</a></h1><div class="epigraph"><p>模型卡不是营销页。它记录预期用途、评测条件、失败模式与数据边界，让下一手决定能不能接这个权重。</p><footer>—— Mitchell 等, Model Cards for Model Reporting</footer></div><p><a href="/llm/benchmark-saturation">上一课</a>要求把饱和卷降级。若报告里只留一张高峰表，降级不会发生。本课写模型卡。协议单元在此收束：数字怎么来，要能写进一张可审计的卡。下一单元换裁判——卡上的「更好用」往往来自法官或人，而不是 harness。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mitchell 等人把模型卡写成类似数据表的短文档：谁训练的、训练数据边界、预期用户、量化指标、伦理考量。LLM 时代还要加：聊天模板、上下文长度、工具接口、<a href="/llm/eval-contamination">污染</a>重叠表、评测框架哈希、解码超参。缺任何一项，外部就无法复现你卡上的数字。</p><p>常见失败：用 Arena 分代理数学能力；用英文榜代理多语言产品；把量化前后的 PPL 当唯一质量声明。本课程前十课拆开的仪器，应在卡上分栏出现，而不是折成一个「综合分」。</p><p><span class="marginnote">开源权重的模型卡还要写清许可证与训练数据是否可审计。只写「混合互联网数据」等于不可审计，与 Dolma 一类公开配方不在同一证据层级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小栏目：用途与非用途；架构与上下文；训练数据与截止日期；评测表（任务、协议、框架版本、是否 CoT / 工具）；已知失败模式；安全与拒答行为的概述（细节走后课危险能力，不在此展开攻击面）；环境与能耗若可测则写。每条分数旁注明仪器，不把 Elo、ECE、pass@1 排进同一列排序。</p><p>更新权重要发新卡或明确 diff，禁止在旧卡上静默改数。</p>',10)),(e(),d(h,null,{default:t(()=>[p(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20INST%5B%22%E4%BB%AA%E5%99%A8%E4%B8%8E%E7%89%88%E6%9C%AC%22%5D%0A%20%20INST%20--%3E%20CARD%5B%22%E6%A8%A1%E5%9E%8B%E5%8D%A1%E6%A0%8F%E7%9B%AE%22%5D%0A%20%20CARD%20--%3E%20USE%5B%22%E7%94%A8%E9%80%94%20%2F%20%E9%9D%9E%E7%94%A8%E9%80%94%22%5D%0A%20%20CARD%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%E6%A8%A1%E5%BC%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卡的读者是部署者，不是排行榜观众。部署者需要的是条件：在什么提示、什么语言、什么工具下，哪些数字成立。把条件写全，分数才会从广告变回测量。省略条件等价于声称无条件成立，这在饱和与格式敏感之后已经不成立。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型卡不替代安全报告或数据卡（Gebru 等 Datasheets）。下一单元从「谁来判开放生成」开始，那些数字更依赖协议，更需要写进卡的脚注。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型卡记录条件与边界，不只记录高峰分。</li><li>不同仪器分栏；饱和卷标明为回归门槛。</li><li>权重更新必须有卡的 diff。</li><li>出处：Mitchell 等 <em>Model Cards for Model Reporting</em>；数据侧对照 Gebru 等 Datasheets。</li></ul>',6))])}const B=o(m,[["render",c]]);export{T as __pageData,B as default};
